import AppKit
let out = NSImage(size:NSSize(width:1104,height:1200))
out.lockFocus()
NSColor.black.setFill(); NSRect(x:0,y:0,width:1104,height:1200).fill()
for i in 0..<24 {
 if let img = NSImage(contentsOfFile:"/tmp/legend-video-camera/frame-\(i).png") {
 let x = (i%6)*184; let y = 1200-(i/6+1)*300
 img.draw(in:NSRect(x:x,y:y,width:184,height:280))
 ("\(i)s" as NSString).draw(at:NSPoint(x:x+8,y:y+281),withAttributes:[.foregroundColor:NSColor.white,.font:NSFont.systemFont(ofSize:14)])
 }
}
out.unlockFocus()
let rep = NSBitmapImageRep(data:out.tiffRepresentation!)!
try rep.representation(using:.png,properties:[:])!.write(to:URL(fileURLWithPath:"/tmp/legend-video-camera/sheet.png"))

