import Foundation
import AVFoundation
import AppKit
let url = URL(fileURLWithPath: CommandLine.arguments[1])
let asset = AVURLAsset(url: url)
let duration = CMTimeGetSeconds(asset.duration)
print("Duração: \(duration) segundos")
let gen = AVAssetImageGenerator(asset: asset)
gen.appliesPreferredTrackTransform = true
gen.maximumSize = CGSize(width: 640, height: 400)
let times = stride(from: 0.0, to: duration, by: 1.0)
for t in times {
 if let cg = try? gen.copyCGImage(at: CMTime(seconds:t, preferredTimescale:600), actualTime:nil) {
 let rep = NSBitmapImageRep(cgImage:cg)
 try rep.representation(using:.png, properties:[:])!.write(to:URL(fileURLWithPath:"/tmp/legend-video-camera/frame-\(Int(t)).png"))
 }
}

